#!/usr/bin/env bash
set -euo pipefail

# build-package.sh — produce a redistributable tarball of Hive.
#
# Output: dist/hive-<version>.tar.gz + dist/hive-<version>.sha256
#
# The tarball extracts to a single top-level directory (hive-<version>/) so
# users get a clean working tree. Excludes:
#   - venv/                      (recreated by install.sh on the target machine)
#   - dist/                      (don't ship build artifacts)
#   - __pycache__/, *.pyc        (Python build leftovers)
#   - .git, .gitignore           (no VCS state)
#   - share/docs/MCP-TOOLS.md    (regenerated by install.sh from current tools)
#   - any .company/, .worktrees/ test artifacts
#
# Usage: build-package.sh [--version X.Y.Z] [--out-dir DIR]
#
# Run from anywhere: the script resolves paths relative to itself.

SOURCE_DIR="$(cd "$(dirname "$0")/.." && pwd)"
OUT_DIR="$SOURCE_DIR/dist"
VERSION=""

# The shared entry-set parser (S2): the staged set is defined once in
# packaging/entries.list and shared with install.sh --copy-to.
. "$SOURCE_DIR/packaging/entries.sh"

while [ $# -gt 0 ]; do
  case "$1" in
    --version) VERSION="$2"; shift 2 ;;
    --out-dir) OUT_DIR="$2"; shift 2 ;;
    -h|--help)
      cat <<EOF
Usage: build-package.sh [--version X.Y.Z] [--out-dir DIR]
  --version  Override version (default: read from VERSION file)
  --out-dir  Where to put the tarball (default: $SOURCE_DIR/dist)
EOF
      exit 0 ;;
    *) echo "Unknown option: $1" >&2; exit 1 ;;
  esac
done

if [ -z "$VERSION" ]; then
  if [ -f "$SOURCE_DIR/VERSION" ]; then
    VERSION="$(tr -d '[:space:]' < "$SOURCE_DIR/VERSION")"
  else
    VERSION="0.0.0-dev"
  fi
fi

PKG_NAME="hive-$VERSION"
TARBALL="$OUT_DIR/${PKG_NAME}.tar.gz"
CHECKSUM="$OUT_DIR/${PKG_NAME}.sha256"

mkdir -p "$OUT_DIR"

# Build a clean copy in a temp dir so we can prune without disturbing the source
STAGE="$(mktemp -d -t hive-build-XXXXXX)"
trap 'rm -rf "$STAGE"' EXIT

echo "Staging Hive $VERSION → $STAGE/$PKG_NAME"
mkdir -p "$STAGE/$PKG_NAME"

# Copy exactly the shared entry set (packaging/entries.list — the ONE
# list; install.sh --copy-to stages the same set, S2). Directories go
# through tar --exclude, not cp -r: cp -r walks the LIVE tree, and
# while a test suite runs (xdist workers importing mid-build)
# __pycache__ files appear and vanish mid-copy — "cp: cannot stat
# ...pyc.<tmp>" kills the build (2026-11-04 CI flake). tar's exclude
# prunes those paths at copy time, so the race cannot occur.
DIRS=()
FILES=()   # "SRC DEST" pairs
while read -r SRC DEST; do
  if [ ! -e "$SOURCE_DIR/$SRC" ]; then
    echo "  NOTE: entry '$SRC' missing from the source — skipped"
    continue
  fi
  if [ -d "$SOURCE_DIR/$SRC" ]; then
    DIRS+=("$SRC")
  else
    FILES+=("$SRC $DEST")
  fi
done < <(entry_pairs "$SOURCE_DIR/packaging/entries.list")

# Top-level public-surface files ship VERBATIM. Regenerating
# INSTALL/LICENSE from heredocs here is how a stale version-pinned
# INSTALL header and the truncated 324-byte LICENSE got back into
# published tarballs after the repo files were fixed (D.2) — and
# B.1-B.3 extended the surface beyond README/INSTALL/LICENSE (release
# history, contributor and security docs). No regeneration, ever.
for PAIR in "${FILES[@]}"; do
  SRC="${PAIR%% *}"; DEST="${PAIR##* }"
  cp "$SOURCE_DIR/$SRC" "$STAGE/$PKG_NAME/$DEST"
done

if [ ${#DIRS[@]} -gt 0 ]; then
  tar -C "$SOURCE_DIR" -cf - \
    --exclude='__pycache__' --exclude='*.pyc' --exclude='*.pyc.*' \
    --exclude='*.pyo' \
    "${DIRS[@]}" | tar -C "$STAGE/$PKG_NAME" -xf -
fi

# Prune things that shouldn't ship
echo "Pruning build artifacts and caches..."
find "$STAGE/$PKG_NAME" -type d -name '__pycache__' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name '.git' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name 'venv' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name 'dist' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name '.company' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name '.worktrees' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -type d -name 'node_modules' -prune -exec rm -rf {} +
find "$STAGE/$PKG_NAME" -name '*.pyc' -delete
find "$STAGE/$PKG_NAME" -name '*.pyo' -delete
find "$STAGE/$PKG_NAME" -name '.DS_Store' -delete
find "$STAGE/$PKG_NAME" -name '*.swp' -delete

# Make sure scripts are executable
chmod +x "$STAGE/$PKG_NAME/bin/hive"
chmod +x "$STAGE/$PKG_NAME/lib/core/"*.sh
chmod +x "$STAGE/$PKG_NAME/lib/tools/"*.sh
chmod +x "$STAGE/$PKG_NAME/packaging/"*.sh

# The shipping manifest (S1, 0.12): the EXACT entry list of the staged
# package, written into the package itself before tarring, so the
# tarball carries its own bill of materials. The staging list above is
# hand-maintained and D.2 proved the shipped surface can drift from the
# public surface with no guard firing; gate 4 of packaging/cut-release.sh
# now verifies THIS list from the tarball (required runtime entries
# present, runtime-state entries absent). MANIFEST.txt lists itself —
# the entry set is everything the tarball contains.
# Published atomically (T1, 0.13): tmp name + rename, so the final
# name appears complete or not at all — the 2026-11-08 CI flake (run
# 42520823326) observed the manifest present at write time and absent
# at tar time with no tar warning; no in-place window is left for it.
(
  cd "$STAGE/$PKG_NAME"
  { find . -type f ! -path './MANIFEST.txt' ! -path './MANIFEST.txt.tmp' \
      | sed 's|^\./||'; \
    echo 'MANIFEST.txt'; } | LC_ALL=C sort > MANIFEST.txt.tmp
  mv MANIFEST.txt.tmp MANIFEST.txt
)
echo "Manifest: $(wc -l < "$STAGE/$PKG_NAME/MANIFEST.txt") entries → $PKG_NAME/MANIFEST.txt"

# Build deterministic tarball (sorted file list, owner/group zeroed, mtimes
# pinned to a STABLE per-release anchor). Anchoring to the VERSION file's
# mtime was broken: cutting a release edits VERSION, which changes the mtime,
# which changed every rebuild's bytes for an otherwise identical tree.
#
# Anchor resolution (SOURCE_DATE_EPOCH convention):
#   1. $SOURCE_DATE_EPOCH, if set — the operator/CI pins it per release
#   2. the last git commit that touched VERSION — stable across rebuilds of
#      the same tree (a release cut commits the new VERSION; rebuilding the
#      same tag reproduces the bytes exactly, and `touch VERSION` no longer
#      changes the hash)
#   3. the HEAD commit date (shallow clones where VERSION's history is
#      missing)
#   4. fixed epoch 0 for trees outside git
if [ -n "${SOURCE_DATE_EPOCH:-}" ]; then
  MTIME_ANCHOR="$SOURCE_DATE_EPOCH"
  MTIME_SOURCE="SOURCE_DATE_EPOCH"
elif MTIME_ANCHOR="$(git -C "$SOURCE_DIR" log -1 --format=%ct -- VERSION 2>/dev/null)" && [ -n "$MTIME_ANCHOR" ]; then
  MTIME_SOURCE="git commit date of VERSION"
elif MTIME_ANCHOR="$(git -C "$SOURCE_DIR" log -1 --format=%ct HEAD 2>/dev/null)" && [ -n "$MTIME_ANCHOR" ]; then
  MTIME_SOURCE="git HEAD commit date"
else
  MTIME_ANCHOR=0
  MTIME_SOURCE="fixed epoch (not a git tree)"
fi

echo "Creating tarball... (mtime anchor: @$MTIME_ANCHOR — $MTIME_SOURCE)"
tar --create --gzip \
  --owner=0 --group=0 \
  --sort=name \
  --mtime="@$MTIME_ANCHOR" \
  -f "$TARBALL" \
  -C "$STAGE" "$PKG_NAME"

# Self-verify the S1 invariant FROM THE TARBALL (T1, 0.13). The 2026-11-08
# CI flake (run 42520823326, 3.12 full row): the staged MANIFEST.txt was
# read back (215 entries) and then the tarball carried it not — the
# failure surfaced only at gate 4 on the cut path, with no forensics and
# no producer-side check to name it. The producer now verifies its own
# output; a miss fails the build and dumps the staging-vs-tarball diff
# so the next occurrence is explained, not guessed. Gate 4 still re-
# verifies on the cut path (the defense in depth, not the first line).
# Capture the listing BEFORE checking it: `tar | grep -q` dies by
# SIGPIPE under set -o pipefail the moment grep exits on the match
# (tar gets 141 on its next write, the pipeline fails, a healthy
# tarball is reported missing its manifest) — the same class gate 7's
# sed-not-head note pins for the release notes. Gate 4 above uses this
# exact capture-then-check shape for the same reason.
TARBALL_LISTING="$(tar -tzf "$TARBALL" 2>/dev/null)" || {
  echo "FAIL: cannot list the tarball (tar exited non-zero) — the" >&2
  echo "      archive is corrupt or incomplete; not shipping it." >&2
  exit 1
}
case "$TARBALL_LISTING" in
  *"/MANIFEST.txt"*) : ;;
  *)
    {
      echo "FAIL: the tarball does not carry MANIFEST.txt — the staged"
      echo "      package carried it a moment ago; the tar dropped it."
      echo "      Forensics (the diff below names what the tar missed):"
      echo "      --- staged files (find) ---"
      ( cd "$STAGE/$PKG_NAME" 2>/dev/null && \
        find . -type f | sed 's|^\./||' | LC_ALL=C sort ) || \
        echo "      (staged package gone: $STAGE/$PKG_NAME)"
      echo "      --- staged MANIFEST.txt ---"
      cat "$STAGE/$PKG_NAME/MANIFEST.txt" 2>/dev/null || \
        echo "      (staged MANIFEST.txt gone)"
      echo "      --- tarball listing ---"
      printf '%s\n' "$TARBALL_LISTING" | LC_ALL=C sort
      echo "      --- sibling stages (mktemp peers) ---"
      ls -d /tmp/hive-build-* 2>/dev/null || echo "      (none)"
    } >&2
    exit 1
    ;;
esac

# Checksum
( cd "$OUT_DIR" && sha256sum "${PKG_NAME}.tar.gz" > "${PKG_NAME}.sha256" )

echo ""
echo "Built:"
echo "  $TARBALL ($(du -h "$TARBALL" | cut -f1))"
echo "  $CHECKSUM"
echo ""
echo "Install on a target machine:"
echo "  curl -L <url-to-tarball> | tar xz"
echo "  cd $PKG_NAME"
echo "  bash packaging/install.sh --copy-to ~/.local/share/hive"
echo ""
echo "Or via the one-liner installer (defaults to this repo's GitHub release;"
echo "  HIVE_PKG_URL / HIVE_PKG_FILE / HIVE_REPO override):"
echo "  curl -fsSL https://raw.githubusercontent.com/fredjt/hive/main/packaging/install-online.sh | sh"
